cypress_script:
describe('Buttons functionality tests', () => {
  it('should successfully click the Click Me button', () => {
    cy.visit('https://demoqa.com/buttons');
    cy.get('button#sp5Bi').click();
    // Assert that the URL did not change, or another relevant element is still visible
  });

  it('should not perform an action on a right-click without appropriate event handling', () => {
    cy.visit('https://demoqa.com/buttons');
    cy.get('button#rightClickBtn').rightclick();
    // Assert the URL did not change or that another element is still visible
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

 test.describe('Buttons functionality tests', () => {
   test('should successfully click the Click Me button', async ({ page }) => {
     await page.goto('https://demoqa.com/buttons');
     await page.click('button#sp5Bi');
     // Assert that the URL did not change, or another relevant element is still visible
   });

   test('should not perform an action on a right-click without appropriate event handling', async ({ page }) => {
     await page.goto('https://demoqa.com/buttons');
     await page.click('button#rightClickBtn', { button: 'right' });
     // Assert the URL did not change or that another element is still visible
   });
 });
